<script module lang="ts">
/**
 * A side pane that shows one artifact a turn produced (`design/components/artifact-pane.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/artifact-pane.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy, type Snippet } from 'svelte'

import {
  Icon,
  Render,
  agentMember,
  focusAfterRemoval,
  joinSlot,
  watchEffect,
} from '@polymorph/svelte'
import styles from '@polymorph/recipes/ai/artifact-pane.module.css'
import Button from '../controls/Button.svelte'
import SegmentedControl from '../controls/SegmentedControl.svelte'
import Spinner from '../structure/Spinner.svelte'

export type ArtifactKind = 'code' | 'document' | 'data' | 'preview'

export interface ArtifactView {
  id: string
  label: string
  content: Snippet | string
}

export interface ArtifactPaneProps {
  /**
   * The header's controls (copy, download, open), as `ghost/neutral/sm` Buttons.
   */
  actions?: Snippet
  /**
   * The body when `views` is absent or empty. A non-empty `views` replaces it.
   */
  children?: Snippet
  /**
   * The close button's accessible name (generic default `Close`), which localized hosts replace.
   */
  closeLabel?: string
  defaultView?: string
  /**
   * The artifact's kind, which picks the mark (the tier's `artifact` glyph when absent).
   */
  kind?: 'code' | 'document' | 'data' | 'preview'
  /**
   * One preformatted line under the title, such as "TypeScript · 142 lines".
   */
  meta?: string
  /**
   * Shows the close button when supplied, and the app decides whether the pane stays mounted.
   */
  onClose?: () => void
  onViewChange?: (id: string) => void
  /**
   * Whether the artifact is still being written, which shows a spinner and sets `aria-busy`.
   */
  streaming?: boolean
  /**
   * The artifact's name, used as the pane's heading and accessible name.
   */
  title: string
  view?: string
  /**
   * The artifact's views (code, preview). Two or more draw a switch, and a single view is drawn
   * with no switch. When `views` is absent or empty, `children` is the body.
   */
  views?: ArtifactView[]
  /**
   * The switch's accessible name (generic default `View`).
   */
  viewsLabel?: string
}
</script>

<script lang="ts">
let {
  actions,
  children,
  closeLabel = 'Close',
  defaultView,
  kind,
  meta,
  onClose,
  onViewChange,
  streaming = false,
  title,
  view,
  views,
  viewsLabel = 'View',
}: ArtifactPaneProps = $props()
const uid = $props.id()
const joined = joinSlot(undefined, () => ({}))
const listening = {
  get close() {
    return onClose !== undefined
  },
  get viewChange() {
    return onViewChange !== undefined
  },
}
const slots = {
  get actions() {
    return actions
  },
  get default() {
    return children
  },
}
let overflowing = $state(false)
// svelte-ignore state_referenced_locally
let mirror = $state(defaultView ?? views?.[0]?.id)
let body = $state<HTMLElement | null>(null)
let closer = $state<HTMLElement | null>(null)
let pane = $state<HTMLElement | null>(null)
let switcher = $state<HTMLElement | null>(null)
const titleId = $derived(`${uid}-title`)
const current = $derived(view ?? mirror)
const switching = $derived(views !== undefined && views.length > 1)
const shown = $derived(
  views === undefined ? undefined : (views.find((entry) => entry.id === current) ?? views[0]),
)
const mark = $derived(
  kind === undefined
    ? 'artifact'
    : ({ code: 'terminal', document: 'document', data: 'table', preview: 'browser' } as const)[
        kind
      ],
)
const choices = $derived((views ?? []).map((entry) => ({ value: entry.id, label: entry.label })))
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const ran = focusAfterRemoval(pane)
  release1 = () => {
    ran()
  }
}
watchEffect(effect1, { watch: () => pane })
onDestroy(() => release1?.())
let release2: (() => void) | undefined
const effect2 = () => {
  release2?.()
  const run = () => {
    overflowing = body !== null && body.scrollHeight > body.clientHeight
  }
  const resize = typeof ResizeObserver === 'undefined' ? undefined : new ResizeObserver(run)
  for (const element of [body, body?.firstElementChild]) if (element) resize?.observe(element)
  release2 = () => {
    resize?.disconnect()
  }
  run()
}
watchEffect(effect2, { watch: () => shown?.id })
onDestroy(() => release2?.())
let release3: (() => void) | undefined
const effect3 = () => {
  release3?.()
  const ran = agentMember({
    member: 'ArtifactPane',
    element: () => pane,
    state: () => ({
      view: shown?.id ?? null,
      views: (views ?? []).map((entry) => ({ id: entry.id, label: entry.label })),
      streaming: streaming,
    }),
    actions: {
      choose: {
        argument: 'id',
        run: (value) => value !== shown?.id && ((mirror = value), onViewChange?.(value)),
      },
      close: () =>
        (() => {
          if (!listening.close) throw new Error('The pane has no close control.')
          onClose?.()
        })(),
    },
    withholds: () => [switcher, closer],
  })
  release3 = () => {
    ran()
  }
}
watchEffect(effect3)
onDestroy(() => release3?.())
</script>

{@render joined.start?.()
}{#if joined.shown
  }<section
    bind:this={pane}
    class={styles.pane}
    aria-labelledby={titleId}
    data-kind={kind}
    data-state={(streaming) ? 'streaming' : undefined}
    aria-busy={(streaming) ? true : undefined}
    data-member="artifact-pane"
    ><header class={styles.header}
      ><span class={styles.mark}
        >{#if streaming
          }<Spinner size="sm" label={`${title}: still being written`}
        />{:else
          }<Icon name={mark} size="sm"
        />{/if
      }</span
      ><div class={styles.heading}
        ><h2 class={styles.title} id={titleId}>{title}</h2
        >{#if meta !== undefined}<p class={styles.meta}>{meta}</p>{/if
      }</div
      >{#if switching
        }<div bind:this={switcher} class={styles.views}
          ><SegmentedControl
            size="sm"
            label={viewsLabel}
            options={choices}
            value={current}
            onChange={(event) => { (mirror = event, onViewChange?.(event)) }}
        /></div
      >{/if
      }{#if slots.actions}<div class={styles.actions}>{@render actions?.()}</div>{/if
      }{#if listening.close
        }<div bind:this={closer} class={styles.close}
          ><Button
            variant="ghost"
            tone="neutral"
            size="sm"
            iconOnly={true}
            icon="close"
            label={closeLabel}
            onClick={() => { onClose?.() }}
        /></div
      >{/if
    }</header
    ><div
      bind:this={body}
      class={styles.body}
      data-view={shown?.id}
      tabindex={((overflowing) ? 0 : undefined) as never}
      role={(overflowing) ? 'group' : undefined}
      aria-labelledby={(overflowing) ? titleId : undefined}
      ><div class={styles.content}
        >{#if shown === undefined
          }{@render children?.()
        }{:else if typeof shown.content === 'string'
          }{shown.content
        }{:else
          }<Render node={shown.content}
        />{/if
      }</div
    ></div
  ></section
>{/if
}{@render joined.end?.()}
